-- ============================================================
-- Migracion 077: catalogo de sectores empresariales.
--
-- Lote A del plan "Perfil inteligente de empresa" (fusion de UX/
-- funcionalidad de SISSO Demo hacia SISSO Plataforma, Fase 1
-- documentada en AUDITORIA_PARIDAD_DEMO_VS_PLATAFORMA.md).
--
-- La Demo (SISSO-demo-main/index.html) tenia este catalogo
-- hardcodeado en una constante de JavaScript en el navegador
-- (var SECTORES = {...}, 12 sectores). Aqui se convierte en un
-- catalogo real de base de datos, tal como el plan lo exige
-- explicitamente ("NO dejarlos unicamente como datos hardcodeados
-- del frontend"), y se agregan 2 sectores mas ("oficina" y "otro")
-- que el plan pide y que la Demo no tenia.
--
-- DISENO:
--   - Tabla GLOBAL, sin organizacion_id: es un catalogo de
--     referencia compartido por todas las organizaciones, igual
--     que catalogo_cie10 (migration_006) -- que tampoco tiene RLS
--     ni organizacion_id por el mismo motivo: no es un dato de
--     ninguna organizacion en particular, es informacion de
--     referencia que la aplicacion consulta.
--   - Los campos "riesgos" NO incluyen los valores de color/fondo
--     CSS puntuales que traia la Demo (ej. 'var(--red2)'): eso es
--     un detalle de presentacion que pertenece a la capa visual
--     compartida (Fase 7/8 del plan -- "el color del sector debe
--     utilizarse solamente como color de acento, no sustituir la
--     paleta principal SISSO"). El frontend debe mapear el campo
--     "nivel" (alto/medio/bajo) a los tokens de color compartidos,
--     no leer un color hardcodeado desde el catalogo.
--   - "puestos_frecuentes" queda como arreglo vacio en el seed: la
--     Demo no tenia ese dato (aunque el plan lo pide); se deja el
--     campo listo para que el superadmin lo complete via el CRUD
--     de esta misma migracion, en vez de inventar datos que no
--     existian en ninguna fuente real.
--   - Escritura (POST/PUT/DELETE) reservada a superadmin a nivel de
--     aplicacion (ver catalogoSectoresRoutes.js), igual que el
--     patron ya usado para otros catalogos globales editables
--     (ver cargadorCie10.js). No hace falta RLS porque no hay
--     organizacion_id que aislar.
-- ============================================================

CREATE TABLE IF NOT EXISTS catalogo_sectores (
    id                          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    clave                       VARCHAR(50) UNIQUE NOT NULL,
    etiqueta                    VARCHAR(150) NOT NULL,
    icono                       VARCHAR(20),
    color_acento                VARCHAR(20),
    color_fondo                 VARCHAR(20),
    descripcion                 TEXT,
    riesgos                     JSONB NOT NULL DEFAULT '[]'::jsonb,
    areas                       JSONB NOT NULL DEFAULT '[]'::jsonb,
    examenes_sugeridos          JSONB NOT NULL DEFAULT '[]'::jsonb,
    herramientas_ergonomicas    JSONB NOT NULL DEFAULT '[]'::jsonb,
    epp_sugerido                JSONB NOT NULL DEFAULT '[]'::jsonb,
    kpis_sugeridos              JSONB NOT NULL DEFAULT '[]'::jsonb,
    puestos_frecuentes          JSONB NOT NULL DEFAULT '[]'::jsonb,
    activo                      BOOLEAN NOT NULL DEFAULT true,
    orden                       INTEGER NOT NULL DEFAULT 0,
    creado_en                   TIMESTAMPTZ NOT NULL DEFAULT now(),
    actualizado_en              TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_catalogo_sectores_activo ON catalogo_sectores(activo);

-- ------------------------------------------------------------
-- Semilla: 14 sectores (12 migrados desde SISSO Demo + 2 nuevos
-- exigidos por el plan: "oficina" y "otro"). Idempotente: si esta
-- migracion se corre dos veces, no duplica filas.
-- ------------------------------------------------------------
