-- ------------------------------------------------------------
-- Trigger para mantener actualizado_en al dia en cada UPDATE
-- (mismo patron simple usado en otras tablas de catalogo editable).
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION fn_actualizar_timestamp_catalogo_sectores()
RETURNS TRIGGER AS $$
BEGIN
  NEW.actualizado_en = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_catalogo_sectores_actualizado_en ON catalogo_sectores;
CREATE TRIGGER trg_catalogo_sectores_actualizado_en
  BEFORE UPDATE ON catalogo_sectores
  FOR EACH ROW EXECUTE FUNCTION fn_actualizar_timestamp_catalogo_sectores();

INSERT INTO schema_migrations (version) VALUES ('077_catalogo_sectores')
ON CONFLICT (version) DO NOTHING;
